  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
  return { col, row: Number(m[2]) }
}
function colName(c) {
  if (c <= 26) return String.fromCharCode(64 + c)
  const x = c - 27
  return String.fromCharCode(65 + Math.floor(x / 26)) + String.fromCharCode(65 + (x % 26))
}
const key = (a) => colName(a.col) + a.row

// ---- read sheet
const lines = fs.readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
lines.forEach((raw, i) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
  const text = m[1]
  const a = parseAddr(text)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${text}`)
  const k = key(a)
  if (cells.has(k)) fail(`error: line ${i + 1}: cell ${text} is declared twice`)
  cells.set(k, { addr: a, content: m[2], line: i + 1 })
})

// ---- formula parsing
function tokenize(s) {
  const t = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { t.push({ t: 'n', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { t.push({ t: 'w', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=)/.exec(s.slice(i)))) { t.push({ t: 'o', v: m[0] }); i += 2; continue }
    if ('^*/+-=<>(),:'.includes(c)) { t.push({ t: 'o', v: c }); i++; continue }
    return null
  }
  return t
}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const bad = new Error('syntax')
  const isOp = (v) => p < toks.length && toks[p].t === 'o' && toks[p].v === v
  const nextIsParen = () => p + 1 < toks.length && toks[p + 1].t === 'o' && toks[p + 1].v === '('
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'o' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = sign()
    if (isOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function sign() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { type: 'un', op, x: sign() } }
    return atom()
  }
  function atom() {
    if (p >= toks.length) throw bad
    const tk = toks[p]
    if (tk.t === 'n') { p++; return { type: 'num', v: tk.v } }
    if (tk.t === 'o' && tk.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) throw bad
      p++
      return { type: 'paren', x: e }
    }
    if (tk.t === 'w') {
      if (nextIsParen()) {
        p += 2
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            throw bad
          }
        }
        return { type: 'call', name: tk.v.toUpperCase(), args }
      }
      p++
      if (isOp(':')) {
        p++
        if (p >= toks.length || toks[p].t !== 'w' || nextIsParen()) throw bad
        const b = toks[p++].v
        return { type: 'range', a: tk.v, b }
      }
      const u = tk.v.toUpperCase()
      if (u === 'TRUE') return { type: 'bool', v: true }
      if (u === 'FALSE') return { type: 'bool', v: false }
      return { type: 'ref', a: tk.v }
    }
    throw bad
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch { return null }
}

// does the tree contain a misplaced range?
function misplaced(n, direct) {
  switch (n.type) {
    case 'range': return !direct
    case 'bin': return misplaced(n.l) || misplaced(n.r)
    case 'un': return misplaced(n.x)
    case 'paren': return misplaced(n.x)
    case 'call': return n.args.some((a) => misplaced(a, true))
    default: return false
  }
}

// ---- evaluation
const FUNCS = { SUM: 1, MIN: 1, MAX: 1, COUNT: 1, AVG: 1, ABS: 1, IF: 1 }
const memo = new Map()
const busy = new Set()

function cellValue(a) {
  const k = key(a)
  if (memo.has(k)) return memo.get(k)
  const c = cells.get(k)
  if (!c) return num(0)
  if (busy.has(k)) return err('#CYCLE!')
  busy.add(k)
  const v = evalCell(c)
  busy.delete(k)
  memo.set(k, v)
  return v
}

function evalCell(c) {
  const s = c.content
  if (s[0] === '=') {
    const ast = parseFormula(s.slice(1))
    if (!ast || misplaced(ast, false)) return err('#ERR!')
    return ev(ast)
  }
  if (s === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
  if (ERRS.has(s)) return err(s)
  return { k: 'text', v: s }
}

function toNum(v) {
  if (v.k === 'num') return v
  if (v.k === 'bool') return num(v.v ? 1 : 0)
  if (v.k === 'text') return err('#VALUE!')
  return v
}
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

function rank(v) { return v.k === 'num' ? 0 : v.k === 'text' ? 1 : 2 }
function cmpCP(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d < 0 ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}
function compare(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.k === 'text') return cmpCP(a.v, b.v)
  const x = a.k === 'bool' ? (a.v ? 1 : 0) : a.v
  const y = b.k === 'bool' ? (b.v ? 1 : 0) : b.v
  return x < y ? -1 : x > y ? 1 : 0
}

function expandRange(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return [err('#REF!')]
  const out = []
  const c1 = Math.min(a.col, b.col), c2 = Math.max(a.col, b.col)
  const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push(cellValue({ col: c, row: r }))
  return out
}

function truth(v) {
  if (v.k === 'err') return v
  if (v.k === 'bool') return v.v ? true : false
  if (v.k === 'num') return v.v !== 0
  return err('#VALUE!')
}

function ev(n) {
  switch (n.type) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'bool', v: n.v }
    case 'paren': return ev(n.x)
    case 'ref': {
      const a = parseAddr(n.a)
      return a ? cellValue(a) : err('#REF!')
    }
    case 'un': {
      const x = ev(n.x)
      if (x.k === 'err') return x
      const y = toNum(x)
      if (y.k === 'err') return y
      return n.op === '-' ? num(-y.v) : y
    }
    case 'bin': {
      const l = ev(n.l)
      if (l.k === 'err') return l
      const r = ev(n.r)
      if (r.k === 'err') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const d = compare(l, r)
        const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
        return { k: 'bool', v: res }
      }
      const x = toNum(l); if (x.k === 'err') return x
      const y = toNum(r); if (y.k === 'err') return y
      switch (n.op) {
        case '+': return fin(x.v + y.v)
        case '-': return fin(x.v - y.v)
        case '*': return fin(x.v * y.v)
        case '/': return y.v === 0 ? err('#DIV/0!') : fin(x.v / y.v)
        case '^': return fin(Math.pow(x.v, y.v))
      }
      return err('#ERR!')
    }
    case 'call': return call(n)
  }
  return err('#ERR!')
}

function call(n) {
  const { name, args } = n
  if (!FUNCS[name]) return err('#NAME?')
  if (name === 'IF') {
    if (args.length !== 3 || args.some((a) => a.type === 'range')) return err('#ERR!')
    const c = truth(ev(args[0]))
    if (c && c.k === 'err') return c
    return ev(args[c ? 1 : 2])
  }
  if (args.length < 1) return err('#ERR!')
  if (name === 'ABS') {
    if (args.length !== 1 || args[0].type === 'range') return err('#ERR!')
    const v = ev(args[0])
    if (v.k === 'err') return v
    const x = toNum(v)
    return x.k === 'err' ? x : num(Math.abs(x.v))
  }
  const vals = []
  for (const a of args) {
    if (a.type === 'range') for (const v of expandRange(a)) vals.push(v)
    else vals.push(ev(a))
  }
  const e = vals.find((v) => v.k === 'err')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'num').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'err') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return fin(nums.reduce((s, x) => Math.min(s, x)))
    case 'MAX': return fin(nums.reduce((s, x) => Math.max(s, x)))
    case 'AVG': return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
  return err('#ERR!')
}

// ---- output
const order = [...cells.values()].sort((a, b) => a.addr.col - b.addr.col || a.addr.row - b.addr.row)
const out = []

function fmt(v) {
  if (v.k === 'err') return v.e
  if (v.k === 'bool') return v.v ? 'TRUE' : 'FALSE'
  if (v.k === 'text') return v.v
  return String(Number(v.v.toPrecision(10)))
}

function collect(n, set) {
  switch (n.type) {
    case 'ref': { const a = parseAddr(n.a); if (a) set.set(key(a), a); break }
    case 'range': {
      const a = parseAddr(n.a), b = parseAddr(n.b)
      if (!a || !b) break
      for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
        for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) set.set(colName(c) + r, { col: c, row: r })
      break
    }
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'un': case 'paren': collect(n.x, set); break
    case 'call': n.args.forEach((x) => collect(x, set)); break
  }
}

for (const c of order) {
  const k = key(c.addr)
  if (mode === 'values') out.push(`${k}=${fmt(cellValue(c.addr))}`)
  else {
    const set = new Map()
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      if (ast) collect(ast, set)
    }
    const list = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
    out.push(`${k}:` + list.map((a) => ' ' + key(a)).join(''))
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
